/**
 * The Specwright mark, inlined as a self-contained data URI so an exported catalog
 * carries its own logo with no external asset to ship alongside the .md file. It is the
 * 24×24 activity-bar icon (media/activity-bar-icon.svg) as a base64 PNG.
 *
 * Note: renders in VS Code's Markdown preview and most viewers; GitHub's sanitizer strips
 * `data:` image URIs, so on github.com the heading falls back to the img alt text.
 */
export const SPECWRIGHT_LOGO_DATA_URI =
  "data:image/png;base64,";

export interface MastheadOptions {
  brandLine?: string | undefined;
  /** Headline counts (e.g. "3 features", "12 scenarios") joined into the caption. */
  stats?: string[] | undefined;
}

/**
 * Masthead shared by both catalog exports: the logo inlined in the H1, an optional
 * caption line in small text (the "generated by" brand line plus headline counts), and a
 * horizontal rule separating it from the body. Returned as a block (no trailing blank) so
 * callers can `pushBlock` the rest after it.
 */
export function renderMasthead(title: string, options?: MastheadOptions): string[] {
  const lines = [
    `# <img src="${SPECWRIGHT_LOGO_DATA_URI}" width="24" height="24" alt="Specwright" /> ${title}`,
  ];
  const caption = [options?.brandLine, ...(options?.stats ?? [])]
    .filter((part): part is string => Boolean(part))
    .join(" · ");
  if (caption) {
    lines.push("", `<sub>${caption}</sub>`);
  }
  lines.push("", "---");
  return lines;
}

/** Thin closing footer mirroring the masthead: a rule and a small "Specwright · …" caption. */
export function renderFooter(stats: string[]): string[] {
  const caption = ["Specwright", ...stats].join(" · ");
  return ["---", "", `<sub>${caption}</sub>`];
}

/**
 * Opening tag for a collapsible section: `<details open>` normally, or `<details>` when the
 * export is configured to start collapsed (better for large catalogs).
 */
export function detailsTag(collapsed?: boolean): string {
  return collapsed ? "<details>" : "<details open>";
}

/** English pluralization for a count + noun, e.g. `countLabel(1, "feature")` → "1 feature". */
export function countLabel(count: number, singular: string, plural = `${singular}s`): string {
  return `${count} ${count === 1 ? singular : plural}`;
}
